const fs = require('fs');

function min(a, b) {
    return a < b ? a : b;
}

function max(a, b) {
    return a > b ? a : b;
}

function lucky(i) {
    return i === 1 ? 0n : lucky(Math.floor(i / 2)) * 10n + (i % 2 === 0 ? 4n : 7n);
}

const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
const l = BigInt(input[0]);
const r = BigInt(input[1]);

const aa = new Array(2047);
aa[0] = 4n;
for (let i = 1; i < 2047; i++) {
    aa[i] = lucky(i + 1);
}

let ans = 0n;
for (let i = 0; i < 2047; i++) {
    const prev = i === 0 ? 0n : aa[i - 1];
    const x = max(prev + 1n, l);
    const y = min(aa[i], r);
    if (x <= y) {
        ans += (y - x + 1n) * aa[i];
    }
}

console.log(ans.toString());

